function buildAsanaClient() {
    const asanaPAT = core.getInput('asana-pat');

    // Use v3 API pattern
    const client = asana.ApiClient.instance;
    const token = client.authentications.token;
    token.accessToken = asanaPAT;

    // Add default headers for v3 API
    client.defaultHeaders['asana-enable'] = 'new-sections,string_ids';

    // Return an object that mimics the v1 API structure for backward compatibility
    return {
        tasks: new asana.TasksApi(),
        stories: new asana.StoriesApi(),
        sections: new asana.SectionsApi(),
        users: new asana.UsersApi(),
    };
}

function buildGithubClient(githubPAT) {
    return new octokit.Octokit({
        auth: githubPAT,
    });
}

function buildMattermostClient() {
    const mattermostToken = core.getInput('mattermost-token');
    const mattermostUrl = 'https://chat.duckduckgo.com';

    const client = new Client4();
    client.setUrl(mattermostUrl);
    client.setToken(mattermostToken);

    return client;
}

function getArrayFromInput(input) {
    return input
        ? input
              .split(',')
              .map((item) => item.trim())
              .filter((item) => item !== '')
        : [];
}

function formatErrorMessage(error) {
    if (error?.message) {
        return error.message;
    }
    try {
        return JSON.stringify(error);
    } catch {
        return String(error);
    }
}

function isPlainObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function parseCustomFieldsHash(jsonInput, failureLabel) {
    let parsed;
    try {
        parsed = JSON.parse(jsonInput);
    } catch (error) {
        core.setFailed(`Invalid ${failureLabel} JSON: ${jsonInput}`);
        return null;
    }
    if (!isPlainObject(parsed)) {
        core.setFailed(`${failureLabel} must be a JSON object`);
        return null;
    }
    return parsed;
}

function parseCustomFieldMap(fieldMapInput) {
    const fieldMap = parseCustomFieldsHash(fieldMapInput, 'custom-field-map');
    if (fieldMap === null) {
        return null;
    }
    for (const [pattern, fields] of Object.entries(fieldMap)) {
        if (!isPlainObject(fields)) {
            core.setFailed(`custom-field-map entry for "${pattern}" must be a JSON object`);
            return null;
        }
    }
    return fieldMap;
}

async function isTaskInProject(taskId, projectId) {
    const client = buildAsanaClient();
    try {
        const response = await client.tasks.getTask(taskId, { opt_fields: 'projects.gid' });
        return response?.data?.projects?.some((project) => project.gid === projectId) ?? false;
    } catch (error) {
        console.warn(`Failed to get projects for task ${taskId}:`, error.message);
        return false;
    }
}

async function findAsanaTasks() {
    const triggerPhrase = core.getInput('trigger-phrase');
    // pull_request is present on PR / review / review_comment events; on
    // issue_comment events the PR description is on issue.body instead.
    const prBody = github.context.payload.pull_request?.body ?? github.context.payload.issue?.body;
    if (!prBody) {
        console.info('No pull request context available for task discovery');
        return [];
    }
    const regexString = `${triggerPhrase}\\s*https:\\/\\/app.asana.com\\/(\\d+)\\/((\\d+)\\/)?(project\\/)?(?<project>\\d+)(\\/task)?\\/(?<task>\\d+).*?`;
    const specifiedProjectId = core.getInput('asana-project');
    const regex = new RegExp(regexString, 'g');

    console.info('Looking for asana task link in body:\n', prBody, 'regex:\n', regexString);
    const foundTasks = [];
    let parseAsanaUrl;
    while ((parseAsanaUrl = regex.exec(prBody)) !== null) {
        const taskId = parseAsanaUrl.groups.task;
        const projectId = parseAsanaUrl.groups.project;

        if (!taskId) {
            core.error(`Invalid Asana task URL${triggerPhrase ? ` after trigger-phrase ${triggerPhrase}` : ''}`);
            continue;
        }

        if (specifiedProjectId && specifiedProjectId !== projectId) {
            // Use APIs to check if the task is in the specified project (in case of multi-project tasks)
            const isInProject = await isTaskInProject(taskId, specifiedProjectId);
            if (!isInProject) {
                console.info(`Skipping ${taskId} as it is not in project ${specifiedProjectId}`);
                continue;
            }
        }

        foundTasks.push(taskId);
    }
    console.info(`found ${foundTasks.length} tasksIds:`, foundTasks.join(','));
    return foundTasks;
}

async function createStory(client, taskId, text, isPinned, isHtml = false) {
    try {
        const opts = {};
        const body = {
            data: {
                is_pinned: isPinned,
            },
        };

        if (isHtml) {
            body.data.html_text = text;
        } else {
            body.data.text = text;
        }

        return await client.stories.createStoryForTask(body, taskId, opts);
    } catch (error) {
        console.error('rejecting promise', error);
    }
}

async function createTaskWithComment(client, name, description, comment, projectId) {
    try {
        const body = {
            data: {
                name,
                notes: description,
                is_rendered_as_separator: false,
                projects: [projectId],
            },
        };
        const opts = {};

        const result = await client.tasks.createTask(body, opts);
        const taskId = result.data.gid;
        console.log('task created', taskId);
        const story = await createStory(client, taskId, comment, true);
        return { taskId, commentFailed: story == null };
    } catch (error) {
        console.error('rejecting promise', error);
        return null;
    }
}

async function createIssueTask() {
    const client = buildAsanaClient();
    const issue = github.context.payload.issue;
    const asanaProjectId = core.getInput('asana-project', { required: true });

    console.info('creating asana task from issue', issue.title);

    const taskDescription = `Description: ${issue.body}`;
    const taskName = `Github Issue: ${issue.title}`;
    const taskComment = `Link to Issue: ${issue.html_url}`;

    const result = await createTaskWithComment(client, taskName, taskDescription, taskComment, asanaProjectId);
    if (result == null) {
        core.setFailed(`Failed to create Asana task: ${taskName}`);
    } else if (result.commentFailed) {
        core.setFailed(`Failed to post comment on Asana task ${result.taskId}`);
    }
    return result;
}

async function notifyPRApproved() {
    const client = buildAsanaClient();
    const pullRequest = github.context.payload.pull_request;
    const taskComment = `PR: ${pullRequest.html_url} has been approved`;

    const foundTasks = await findAsanaTasks();

    const comments = [];
    const failures = [];
    for (const taskId of foundTasks) {
        const comment = await createStory(client, taskId, taskComment, false);
        if (comment == null) {
            failures.push(taskId);
        }
        comments.push(comment);
    }

    if (failures.length > 0) {
        core.setFailed(`Failed to post PR approved comments to tasks: ${failures.join(', ')}`);
    }
    return comments;
}

async function addTaskToAsanaProject() {
    const client = buildAsanaClient();

    const projectId = core.getInput('asana-project', { required: true });
    const sectionId = core.getInput('asana-section');
    const explicitTaskIds = getArrayFromInput(core.getInput('asana-task-id'));
    const taskIds = explicitTaskIds.length > 0 ? explicitTaskIds : await findAsanaTasks();

    if (taskIds.length === 0) {
        core.setFailed(`No valid task IDs provided`);
        return;
    }

    const failures = [];
    for (const taskId of taskIds) {
        console.info(`Adding task ${taskId} to project ${projectId}`);
        const result = await addTaskToProject(client, taskId, projectId, sectionId);
        if (!result) {
            failures.push(taskId);
        }
    }

    if (failures.length > 0) {
        core.setFailed(`Failed to add the following tasks to project ${projectId}: ${failures.join(', ')}`);
    }
}

async function updateTaskCustomFieldsAction() {
    const client = buildAsanaClient();

    const taskIds = getArrayFromInput(core.getInput('asana-task-id', { required: true }));
    const customFieldsInput = core.getInput('asana-task-custom-fields', { required: true });

    if (taskIds.length === 0) {
        core.setFailed(`No valid task IDs provided`);
        return;
    }

    const customFields = parseCustomFieldsHash(customFieldsInput, 'custom fields');
    if (customFields === null) {
        return;
    }

    for (let i = 0; i < taskIds.length; i++) {
        const taskId = taskIds[i];
        try {
            await updateTaskCustomFields(client, taskId, customFields);
        } catch (error) {
            console.error(`Error updating custom fields on task ${taskId}:`, JSON.stringify(error));
            const remaining = taskIds.slice(i + 1);
            const suffix = remaining.length ? ` Skipped remaining tasks: ${remaining.join(', ')}.` : '';
            core.setFailed(`Error updating custom fields on task ${taskId}: ${formatErrorMessage(error)}.${suffix}`);
            return;
        }
    }
}

async function updateTaskCustomFields(client, taskId, customFields) {
    console.info(`Updating custom fields on task ${taskId}`);
    await client.tasks.updateTask({ data: { custom_fields: customFields } }, taskId, {});
}

async function updateAsanaTaskTypeStatusAction() {
    const client = buildAsanaClient();
    const taskId = core.getInput('asana-task-id', { required: true });
    const customType = core.getInput('asana-task-custom-type');
    const customTypeStatusOption = core.getInput('asana-task-custom-type-status-option');

    if (!customTypeStatusOption) {
        core.setFailed('asana-task-custom-type-status-option is required');
        return;
    }

    const data = customType
        ? {
              resource_subtype: 'custom',
              custom_type: customType,
              custom_type_status_option: customTypeStatusOption,
          }
        : { custom_type_status_option: customTypeStatusOption };

    try {
        console.info(`Updating custom type/status on task ${taskId}`);
        await client.tasks.updateTask({ data }, taskId, {});
    } catch (error) {
        console.error(`Error updating custom type/status on task ${taskId}:`, JSON.stringify(error));
        core.setFailed(`Error updating custom type/status on task ${taskId}: ${formatErrorMessage(error)}`);
    }
}

async function addTaskToProject(client, taskId, projectId, sectionId) {
    if (!sectionId) {
        console.info('adding asana task to project', projectId);
        try {
            const body = {
                data: {
                    project: projectId,
                    insert_after: null,
                },
            };
            const opts = {};
            return await client.tasks.addProjectForTask(body, taskId, opts);
        } catch (error) {
            console.error('rejecting promise', error);
        }
    } else {
        console.info(`adding asana task to top of section ${sectionId} in project ${projectId}`);
        try {
            const body = {
                data: {
                    project: projectId,
                    section: sectionId,
                },
            };
            const opts = {};
            return await client.tasks.addProjectForTask(body, taskId, opts);
        } catch (error) {
            console.error('rejecting promise', error);
        }
    }
}

