async function createTask(
    client,
    name,
    description,
    projectId,
    sectionId = '',
    tags = [],
    collaborators = [],
    assignee = '',
    customFields = '',
) {
    const taskOpts = {
        name,
        notes: description,
        projects: [projectId],
        tags,
        followers: collaborators,
    };

    if (assignee) {
        taskOpts.assignee = assignee;
    }

    if (customFields) {
        try {
            taskOpts.custom_fields = JSON.parse(customFields);
        } catch (error) {
            console.error(`Invalid custom fields JSON: ${customFields}`);
        }
    }

    if (sectionId) {
        console.log('checking for duplicate task before creating a new one', name);
        const existingTaskId = await findTaskInSection(client, sectionId, name);
        if (existingTaskId === null) {
            return null;
        }
        if (existingTaskId !== '0') {
            console.log('task already exists, skipping');
            core.setOutput('taskId', existingTaskId);
            core.setOutput('duplicate', true);
            return existingTaskId;
        }

        taskOpts.memberships = [{ project: projectId, section: sectionId }];
    }

    const body = { data: taskOpts };
    const opts = {};

    console.log(`creating new task with options:='${JSON.stringify(taskOpts)}'`);
    try {
        const result = await client.tasks.createTask(body, opts);
        const createdTaskId = result.data.gid;
        console.log('task created', createdTaskId);
        core.setOutput('taskId', createdTaskId);
        core.setOutput('duplicate', false);
        return createdTaskId;
    } catch (error) {
        console.error('rejecting promise', JSON.stringify(error));
        return null;
    }
}

async function createAsanaTask() {
    const client = buildAsanaClient();

    const projectId = core.getInput('asana-project', { required: true });
    const sectionId = core.getInput('asana-section');
    const taskName = core.getInput('asana-task-name', { required: true });
    const taskDescription = core.getInput('asana-task-description', { required: true });
    const tags = getArrayFromInput(core.getInput('asana-tags'));
    const collaborators = getArrayFromInput(core.getInput('asana-collaborators'));
    const assignee = core.getInput('asana-task-assignee');
    const customFields = core.getInput('asana-task-custom-fields');

    const result = await createTask(client, taskName, taskDescription, projectId, sectionId, tags, collaborators, assignee, customFields);
    if (result === null) {
        core.setFailed(`Failed to create Asana task: ${taskName}`);
    }
    return result;
}

function matchesPattern(pattern, filePath) {
    if (pattern === filePath) {
        return true;
    }

    const hasLeadingStar = pattern.startsWith('*');
    const hasTrailingStar = pattern.endsWith('*');

    let literal = pattern;
    while (literal.startsWith('*')) {
        literal = literal.slice(1);
    }
    while (literal.endsWith('*')) {
        literal = literal.slice(0, -1);
    }

    if (hasLeadingStar && hasTrailingStar) {
        return literal === '' || filePath.includes(literal);
    }
    if (hasLeadingStar) {
        return filePath.endsWith(literal);
    }
    if (hasTrailingStar) {
        return filePath.startsWith(literal);
    }
    return false;
}

function resolveCustomFieldsForFiles(fieldMap, changedFiles) {
    const fallbackFields = fieldMap['*'];
    const patterns = Object.entries(fieldMap).filter(([pattern]) => pattern !== '*');
    const resolved = {};

    for (const [pattern, fields] of patterns) {
        const anyFileMatches = changedFiles.some((file) => matchesPattern(pattern, file));
        if (!anyFileMatches) {
            continue;
        }
        for (const [fieldGid, value] of Object.entries(fields)) {
            if (!(fieldGid in resolved)) {
                resolved[fieldGid] = value;
            }
        }
    }

    // The "*" fallback only fills in fields that no specific pattern set.
    if (fallbackFields) {
        for (const [fieldGid, value] of Object.entries(fallbackFields)) {
            if (!(fieldGid in resolved)) {
                resolved[fieldGid] = value;
            }
        }
    }

    return resolved;
}

async function getChangedFiles(githubClient, owner, repo, pullNumber) {
    const files = [];
    const perPage = 100;
    let page = 1;

    while (true) {
        const response = await githubClient.request('GET /repos/{owner}/{repo}/pulls/{pull_number}/files', {
            owner,
            repo,
            pull_number: pullNumber,
            per_page: perPage,
            page,
            headers: {
                'X-GitHub-Api-Version': '2022-11-28',
            },
        });
        const data = response.data || [];
        files.push(...data.map((file) => file.filename));
        if (data.length < perPage) {
            break;
        }
        page++;
    }

    return files;
}

async function setCustomFieldsFromDiff() {
    const githubPAT = core.getInput('github-pat', { required: true });
    const githubClient = buildGithubClient(githubPAT);
    const org = core.getInput('github-org', { required: true });
    const repo = core.getInput('github-repository', { required: true });
    const pullNumber = core.getInput('github-pr', { required: true });
    const fieldMapInput = core.getInput('custom-field-map', { required: true });

    const fieldMap = parseCustomFieldMap(fieldMapInput);
    if (fieldMap === null) {
        return;
    }

    const changedFiles = await getChangedFiles(githubClient, org, repo, pullNumber);
    console.info(`PR #${pullNumber} changed ${changedFiles.length} file(s)`);

    const customFields = resolveCustomFieldsForFiles(fieldMap, changedFiles);
    if (Object.keys(customFields).length === 0) {
        console.info('No custom fields matched the changed files; nothing to do');
        return;
    }
    console.info('Setting custom fields:', JSON.stringify(customFields));

    const client = buildAsanaClient();
    const foundTasks = await findAsanaTasks();

    for (let i = 0; i < foundTasks.length; i++) {
        const taskId = foundTasks[i];
        try {
            await updateTaskCustomFields(client, taskId, customFields);
        } catch (error) {
            console.error(`Error updating custom fields on task ${taskId}:`, JSON.stringify(error));
            const remaining = foundTasks.slice(i + 1);
            const suffix = remaining.length ? ` Skipped remaining tasks: ${remaining.join(', ')}.` : '';
            core.setFailed(`Error updating custom fields on task ${taskId}: ${formatErrorMessage(error)}.${suffix}`);
            return;
        }
    }
}

async function addTaskPRDescription() {
    const githubPAT = core.getInput('github-pat');
    const githubClient = buildGithubClient(githubPAT);
    const org = core.getInput('github-org', { required: true });
    const repo = core.getInput('github-repository', { required: true });
    const pr = core.getInput('github-pr', { required: true });
    const projectId = core.getInput('asana-project', { required: true });
    const taskId = core.getInput('asana-task-id', { required: true });

    githubClient
        .request('GET /repos/{owner}/{repo}/pulls/{pull_number}', {
            owner: org,
            repo,
            pull_number: pr,
            headers: {
                'X-GitHub-Api-Version': '2022-11-28',
            },
        })
        .then((response) => {
            console.log(response.data.body);
            const body = response.data.body;
            const asanaTaskMessage = `Task/Issue URL: https://app.asana.com/0/${projectId}/${taskId}/f`;
            const updatedBody = `${asanaTaskMessage} \n\n ----- \n${body}`;

            githubClient
                .request('PATCH /repos/{owner}/{repo}/pulls/{pull_number}', {
                    owner: org,
                    repo,
                    pull_number: pr,
                    body: updatedBody,
                    headers: {
                        'X-GitHub-Api-Version': '2022-11-28',
                    },
                })
                .catch((error) => core.error(error));
        });
}

async function getAsanaUserID() {
    const ghUsername = core.getInput('github-username') || github.context.payload.pull_request.user.login;
    const githubPAT = core.getInput('github-pat', { required: true });
    const githubClient = buildGithubClient(githubPAT);
    const org = 'duckduckgo';
    const repo = 'internal-github-asana-utils';

    console.log(`Looking up Asana user ID for ${ghUsername}`);
    try {
        await githubClient
            .request('GET /repos/{owner}/{repo}/contents/user_map.yml', {
                owner: org,
                repo,
                headers: {
                    'X-GitHub-Api-Version': '2022-11-28',
                    Accept: 'application/vnd.github.raw+json',
                },
            })
            .then((response) => {
                const userMap = yaml.load(response.data);
                if (ghUsername in userMap) {
                    core.setOutput('asanaUserId', userMap[ghUsername]);
                } else {
                    core.setFailed(`User ${ghUsername} not found in user map`);
                }
            });
    } catch (error) {
        core.setFailed(error);
    }
}

